SELECT SG.*, U.id AS `owner.id`, U.login_id AS `owner.loginId`, U.nickname AS `owner.nickname` FROM study_groups SG INNER JOIN users U ON U.id = SG.owner_id WHERE 1 = 1
AND SG.category = #{category}
AND ( LOWER(SG.title) LIKE CONCAT('%', LOWER(#{query}), '%') OR LOWER(SG.description) LIKE CONCAT('%', LOWER(#{query}), '%') OR LOWER(SG.category) LIKE CONCAT('%', LOWER(#{query}), '%') OR LOWER(SG.study_method) LIKE CONCAT('%', LOWER(#{query}), '%') OR LOWER(SG.difficulty) LIKE CONCAT('%', LOWER(#{query}), '%') )
ORDER BY SG.id DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM study_groups SG WHERE 1 = 1
AND SG.category = #{category}
AND ( LOWER(SG.title) LIKE CONCAT('%', LOWER(#{query}), '%') OR LOWER(SG.description) LIKE CONCAT('%', LOWER(#{query}), '%') OR LOWER(SG.category) LIKE CONCAT('%', LOWER(#{query}), '%') OR LOWER(SG.study_method) LIKE CONCAT('%', LOWER(#{query}), '%') OR LOWER(SG.difficulty) LIKE CONCAT('%', LOWER(#{query}), '%') )
